///////////////////////////////////
//  Blocks Categories Palettes
///////////////////////////////////

import ScratchJr from '../ScratchJr';
import Block from '../blocks/Block';
import BlockSpecs from '../blocks/BlockSpecs';
import ScriptsPane from './ScriptsPane';
import Undo from './Undo';
import { getModelRefAs, hasModelRef, findUpModelRefEl } from '../modelRegistry';
import PlatformBridge from '../../platform/PlatformBridge';
import MediaLib from '../../platform/MediaLib';
import Events from '../../utils/Events';
import type Scripts from '../ui/Scripts.js';
import type Sprite from '../engine/Sprite';
import type Page from '../engine/Page';
import type {EncodedStrip} from './Project';
import Rectangle from '../../geom/Rectangle';
import DrawPath from '../../utils/DrawPath';
import ScratchAudio from '../../utils/ScratchAudio';
import Record from './Record';
import {frame, gn, localx, newHTML, scaleMultiplier, isTouch, newDiv,
    setProps, globalx, localy, globaly, drawScaled, newCanvas,
    setCanvasSize, hitRect, writeText, getStringSize} from '../../utils/lib';


let blockscale = 0.75;
let numcat = 0; // getter
let betweenblocks: number | null = null; // Set in setup()
let blockdy = 5;
let timeoutid: NodeJS.Timeout | null = null;
let helpballoon: (HTMLCanvasElement & { icon?: unknown }) | null = null;
let dxblocks = 10;

export default class Palette {
    static blockdx: number;

    static get numcat () {
        return numcat;
    }

    static get helpballoon () {
        return helpballoon;
    }

    static set helpballoon (newHelpballoon) {
        helpballoon = newHelpballoon;
    }

    static setup (parent: HTMLElement) {
        blockscale *= scaleMultiplier;
        blockdy *= scaleMultiplier;
        Palette.blockdx *= scaleMultiplier; // XXX
        betweenblocks = 90 * blockscale;
        Palette.createCategorySelectors(parent);
        var div = newHTML('div', 'palette', parent);
        div.setAttribute('id', 'palette');
        div.onmousedown = function (evt: MouseEvent) {
            Palette.paletteMouseDown(evt);
        };
        var pc = newHTML('div', 'papercut', parent);
        newHTML('div', 'withstyle', pc);
    }

    static createCategorySelectors (parent: HTMLElement) {
        var sel = newHTML('div', 'categoryselector', parent);
        sel.setAttribute('id', 'selectors');
        var bkg = newHTML('div', 'catbkg', sel);
        newHTML('div', 'catimage', bkg);
        var leftPx = 15 * scaleMultiplier;
        var widthPx = 54 * scaleMultiplier;
        for (var i = 0; i < BlockSpecs.categories.length; i++) {
            Palette.createSelector(sel, i, leftPx + i * widthPx, 0, BlockSpecs.categories[i]);
        }
    }

    static paletteMouseDown (e: MouseEvent & { touches?: TouchList }) {
        if (isTouch && e.touches && (e.touches.length > 1)) {
            return;
        }
        if (ScratchJr.onHold) {
            return;
        }
        e.preventDefault();
        ScratchJr.blur();
        var pal = gn('palette')!;
        var spt = Events.getTargetPoint(e);
        var pt = {
            x: localx(pal, spt.x),
            y: localy(pal, spt.y)
        };
        for (var i = 0; i < pal.childElementCount; i++) {
            var ths = pal.childNodes[i] as HTMLElement;
            if (!hitRect(ths, pt)) {
                continue;
            }
            if (ScratchJr.shaking && (ScratchJr.shaking == ths)) {
                Palette.removeSound(ths);
            } else {
                Events.startDrag(e, ths, Palette.prepareForDrag, Palette.dropBlockFromPalette, ScriptsPane.draggingBlock, Palette.showHelp, Palette.startShaking);
            }
        }
        ScratchJr.clearSelection();
    }

    static removeSound (ths: HTMLElement) {
        ScratchAudio.sndFX('cut.wav');
        var indx = getModelRefAs<Block>(ths, 'block')!.getArgValue() as number;
        var spr = ScratchJr.getSprite() as Sprite;
        if (!spr) {
            return;
        }
        var page = getModelRefAs<Page>(spr.div.parentNode as HTMLElement, 'page')!;
        var sounds = spr.sounds.concat();
        if (indx >= sounds.length) {
            return;
        }
        sounds.splice(indx, 1);
        spr.sounds = sounds;
        // recreate the sprite scripts to make sure deleted sound is properly treated
        var sprdata = spr.getData();
        var div = gn(spr.id + '_scripts')!;
        while (div.childElementCount > 0) {
            div.removeChild(div.childNodes[0]);
        }
        var sc = getModelRefAs<Scripts>(div, 'scripts')!;
        var list = sprdata.scripts as EncodedStrip[];
        for (var j = 0; j < list.length; j++) {
            sc.recreateStrip(list[j]);
        }
        Undo.record({
            action: 'deletesound',
            who: spr.id,
            where: page.id,
            sound: name
        });
        ScratchJr.storyStart('Palette.removeSound'); // Record a change for sample projects in story-starter mode

        Palette.selectCategory(3);
    }

    static showHelp (e: Event | null, b: HTMLElement) {
        var block = getModelRefAs<Block>(b, 'block')!;
        var help = BlockSpecs.blockDesc(block, ScratchJr.getSprite()) as { [key: string]: string };
        var str = help[block.blocktype];
        if (!str) {
            return;
        }
        Palette.openPaletteBalloon(b, str);
        timeoutid = setTimeout(Palette.closeHelpBalloon, 2000);
    }

    static startShaking (b: HTMLElement) {
        if (!hasModelRef(b)) {
            return;
        }
        if (getModelRefAs<Block>(b, 'block')!.blocktype != 'playusersnd') {
            Palette.showHelp(null, b); return;
        }
        ScratchJr.shaking = b;
        ScratchJr.stopShaking = Palette.stopShaking;
        b.setAttribute('class', 'shakeme');
        newHTML('div', 'deletesound', b);
    }

    static stopShaking (b: HTMLElement) {
        if (!hasModelRef(b)) {
            return;
        }
        ScratchJr.shaking = undefined;
        ScratchJr.stopShaking = undefined;
        b.setAttribute('class', '');
        var ic = b.childNodes[b.childElementCount - 1] as HTMLElement;
        if (ic.getAttribute('class') == 'deletesound') {
            b.removeChild(ic);
        }
    }

    static openPaletteBalloon (obj: HTMLElement, label: string) {
        if (helpballoon) {
            Palette.closeHelpBalloon();
        }
        var fontSize = Math.floor(14 * window.devicePixelRatio * scaleMultiplier);
        var w = window.devicePixelRatio * 80 * scaleMultiplier;
        var h = window.devicePixelRatio * 36 * scaleMultiplier;
        var dy = globaly(obj) - 36 * scaleMultiplier;
        helpballoon = newCanvas(frame, 0, dy, w, h, {
            position: 'absolute',
            zIndex: 1000
        });
        helpballoon!.icon = obj;
        var ctx = helpballoon!.getContext('2d')!;
        w = 16 * window.devicePixelRatio * scaleMultiplier
            + getStringSize(ctx, 'bold ' + fontSize + 'px ' + window.Settings!.paletteBalloonFont, label).width;
        if (w < 36 * scaleMultiplier) {
            w = 36 * scaleMultiplier;
        }
        var dx = (globalx(obj) + (obj.offsetWidth / 2)) * window.devicePixelRatio - (w / 2);
        setCanvasSize(helpballoon, w, h);
        setProps(helpballoon!.style, {
            position: 'absolute',
            webkitTransform: 'translate(' + (-w / 2) + 'px, ' + (-h / 2) + 'px) '
                + 'scale(' + (1 / window.devicePixelRatio) + ') translate(' + (dx + (w / 2)) + 'px, ' + (h / 2) + 'px)'
        });
        Palette.drawBalloon(helpballoon!.getContext('2d')!, w, h);
        writeText(ctx, 'bold ' + fontSize + 'px ' + window.Settings!.paletteBalloonFont, 'white', label, 21 * window.devicePixelRatio * scaleMultiplier, 8 * window.devicePixelRatio * scaleMultiplier);
    }

    static hide () {
        const blocksPaletteFirst = gn('blockspalette')!.childNodes[0] as HTMLElement;
        const blocksPaletteSecond = gn('blockspalette')!.childNodes[1] as HTMLElement;
        blocksPaletteFirst.style.display = 'none';
        blocksPaletteSecond.style.display = 'none';
    }

    static show () {
        const showFirst = gn('blockspalette')!.childNodes[0] as HTMLElement;
        const showSecond = gn('blockspalette')!.childNodes[1] as HTMLElement;
        showFirst.style.display = 'inline-block';
        showSecond.style.display = 'inline-block';
    }


    static closeHelpBalloon () {
        if (timeoutid) {
            clearTimeout(timeoutid);
        }
        if (helpballoon) {
            helpballoon.parentNode!.removeChild(helpballoon);
        }
        helpballoon = null;
        timeoutid = null;
    }

    static drawBalloon (ctx: CanvasRenderingContext2D, w: number, h: number) {
        var curve = 4;
        var path = [
            ['M', 0, curve], ['q', 0, -curve, curve, -curve], ['h', w - curve * 2],
            ['q', curve, 0, curve, curve], ['v', h - 11 - curve * 2], ['q', 0, curve, -curve, curve],
            ['h', -(w / 2) + curve + 11], ['l', -11, 11], ['l', -11, -11], ['h', -(w / 2) + curve + 11],
            ['q', -curve, 0, -curve, -curve], ['z']
        ];
        ctx.clearRect(0, 0, Math.max(ctx.canvas.width, w), Math.max(ctx.canvas.height, h));
        ctx.fillStyle = '#4682B5';
        ctx.lineWidth = 2;
        //ctx.strokeStyle = 'rgba(242,243,242,0.4)';
        ctx.beginPath();
        DrawPath.render(ctx, path);
        ctx.fill();
    //  ctx.stroke();
    }

    static prepareForDrag (e: MouseEvent) {
        e.preventDefault();
        ScratchAudio.sndFX('grab.wav');
        if (!ScratchJr.runtime.inactive()) {
            ScratchJr.stopStrips();
        }
        var sc = getModelRefAs<Scripts>(ScratchJr.getActiveScript(), 'scripts')!;
        sc.flowCaret = null;
        var pt = Events.getTargetPoint(e);
        Events.dragmousex = pt.x;
        Events.dragmousey = pt.y;
        if (!Events.dragthumbnail.parentNode) { // palette has been removed programatically
            Events.dragthumbnail = Palette.getBlockNamed(getModelRefAs<Block>(Events.dragthumbnail, 'block')!.blocktype) as HTMLElement;
            if (!Events.dragthumbnail) {
                Events.cancelAll();
                return;
            }
        }
        var mx = Events.dragmousex - frame.offsetLeft - localx(Events.dragthumbnail, Events.dragmousex);
        var my = Events.dragmousey - frame.offsetTop - localy(Events.dragthumbnail, Events.dragmousey);
        const dragOwner = getModelRefAs<Block>(Events.dragthumbnail, 'block')!;
        Events.dragcanvas = dragOwner.duplicateBlock(mx, my, sc.spr).div;
        Events.dragcanvas.style.zIndex = String(ScratchJr.dragginLayer);
        Events.dragDiv.appendChild(Events.dragcanvas);
        // Events.dragcanvas.owner.lift();
        sc.dragList = [getModelRefAs<Block>(Events.dragcanvas, 'block')!];
        sc.prepareCaret(getModelRefAs<Block>(Events.dragcanvas, 'block')!);
    }

    static getBlockNamed (str: string) {
        var pal = gn('palette')!;
        for (var i = 0; i < pal.childElementCount; i++) {
            const owner = getModelRefAs<Block>(pal.childNodes[i] as HTMLElement, 'block')!;
            if (owner.blocktype == str) {
                return pal.childNodes[i];
            }
        }
        return null;
    }

    static createSelector (parent: HTMLElement, n: number, dx: number, dy: number, spec: (HTMLImageElement | string)[]) {
        var pxWidth = 51 * scaleMultiplier;
        var pxHeight = 57 * scaleMultiplier;
        var div = newDiv(parent, dx, dy, pxWidth, pxHeight, {
            position: 'absolute'
        });
        div.index = n;
        var officon = (spec[1] as HTMLImageElement).cloneNode(true) as HTMLImageElement;
        officon.width = pxWidth;
        officon.height = pxHeight;
        div.appendChild(officon);
        setProps(officon.style, {
            position: 'absolute',
            zIndex: 6,
            visibility: 'visible'
        });
        var onicon = (spec[0] as HTMLImageElement).cloneNode(true) as HTMLImageElement;
        onicon.width = pxWidth;
        onicon.height = pxHeight;
        div.appendChild(onicon);
        div.bkg = spec[2] as string;
        setProps(onicon.style, {
            position: 'absolute',
            zIndex: 8,
            visibility: 'hidden'
        });
        div.onmousedown = function (evt) {
            Palette.clickOnCategory(evt);
        };
    }

    static clickOnCategory (e: Event) {
        if (!e) {
            return;
        }
        e.preventDefault();
        ScratchJr.unfocus(e);
        var t = e.target as HTMLElement;
        ScratchAudio.sndFX('keydown.wav');
        var index = t.parentNode ? (t.parentNode as HTMLElement).index! : 2;
        Palette.selectCategory(index);
    }

    static selectCategory (n: number) {
        var div = gn('selectors')!;
        // set the icons for text or sprite
        numcat = n;
        var currentSel = div.childNodes[n + 1];
        for (var i = 1; i < div.childElementCount; i++) {
            var sel = div.childNodes[i] as HTMLElement;
            const selFirst = sel.childNodes[0] as HTMLElement;
            const selSecond = sel.childNodes[1] as HTMLElement;
            selFirst.style.visibility = (sel.index != n) ? 'visible' : 'hidden';
            selSecond.style.visibility = (sel.index == n) ? 'visible' : 'hidden';
        }
        var pal = gn('palette')!;
        gn('blockspalette')!.style.background = (currentSel as HTMLElement).bkg!;
        while (pal.childElementCount > 0) {
            pal.removeChild(pal.childNodes[0]);
        }
        if (!ScratchJr.getSprite()) {
            return;
        }
        var list = (BlockSpecs.palettes[n]).concat();
        var dx = dxblocks;
        for (var k = 0; k < list.length; k++) {
            if (list[k] == 'space') {
                dx += 30 * blockscale;
            } else {
                var newb = Palette.newScaledBlock(pal, list[k],
                    ((list[k] == 'repeat') ? 0.65 * scaleMultiplier : blockscale), dx, blockdy);
                newb.lift();
                dx += betweenblocks!;
            }
        }
        dx += 30;
        if ((n == (BlockSpecs.categories.length - 1)) && (ScratchJr.stage.pages.length > 1)) {
            Palette.addPagesBlocks(dx);
        }
        if ((n == 3) && ((ScratchJr.getSprite() as Sprite).sounds.length > 0)) {
            Palette.addSoundsBlocks(dxblocks);
        }
    }

    static reset () {
        if (numcat == (BlockSpecs.categories.length - 1)) {
            Palette.selectCategory(BlockSpecs.categories.length - 1);
        }
        if (numcat == 3) {
            Palette.selectCategory(3);
        }
    }

    static addPagesBlocks (dx: number) {
        var pal = gn('palette')!;
        var spec = BlockSpecs.defs.gotopage as unknown[];
        for (var i = 0; i < ScratchJr.stage.pages.length; i++) {
            if (ScratchJr.stage.pages[i].id == ScratchJr.stage.currentPage.id) {
                continue;
            }
            spec[4] = i + 1;
            var newb = Palette.newScaledBlock(pal, 'gotopage', blockscale, dx, blockdy);
            newb.lift();
            dx += betweenblocks! + 5;
        }
    }

    static addSoundsBlocks (dx: number) {
        var pal = gn('palette')!;
        var spr = ScratchJr.getSprite() as Sprite;
        var list = spr ? spr.sounds : [];
        var newb;
        
        for (var i = 0; i < list.length; i++) {
            var op = (MediaLib.sounds.indexOf(list[i]) < 0) ? 'playusersnd' : 'playsnd';
            var val = (MediaLib.sounds.indexOf(list[i]) < 0) ? i : list[i];
            newb = Palette.addBlockSound(pal, op, val, dx, blockdy);
            newb.lift();
            dx += betweenblocks!;
        }
        if ((list.length < 6) && Record.available && newb) {
            Palette.drawRecordSound(newb.div.offsetWidth, newb.div.offsetHeight, dx);
        }
    }

    static addBlockSound (parent: HTMLElement, op: string, val: string | number, dx: number, dy: number) {
        var spec = BlockSpecs.defs[op] as unknown[];
        var old = spec[4];
        spec[4] = val;
        var newb = Palette.newScaledBlock(parent, op, blockscale, dx, dy);
        spec[4] = old;
        return newb;
    }

    static drawRecordSound (w: number, h: number, dx: number) {
        var pal = gn('palette')!;
        var div = newDiv(pal, dx, 0, w, h, {
            top: (6 * scaleMultiplier) + 'px'
        });
        var cnv = newCanvas(div, 0, 0, div.offsetWidth * window.devicePixelRatio, div.offsetHeight * window.devicePixelRatio, {
                webkitTransform: 'translate('
                + (-div.offsetWidth * window.devicePixelRatio / 2) + 'px, '
                + (-div.offsetHeight * window.devicePixelRatio / 2) + 'px) '
                + 'scale(' + (1 / window.devicePixelRatio) + ') translate('
                + (div.offsetWidth * window.devicePixelRatio / 2) + 'px, '
                + (div.offsetHeight * window.devicePixelRatio / 2) + 'px)'
            }
        );
        if (BlockSpecs.mic.complete) {
            drawScaled(BlockSpecs.mic, cnv);
        } else {
            BlockSpecs.mic.onload = function () {
                drawScaled(BlockSpecs.mic, cnv);
            };
        }
        if (isTouch) {
            div.onmousedown = Palette.recordSound;
        }
    }

    static recordSound (e: MouseEvent) {
        e.preventDefault();
        e.stopPropagation();
        ScratchJr.clearSelection();
        Record.appear();
    }

    // move to scratch jr app
    static getLandingPlace (el: HTMLElement, e: MouseEvent | TouchEvent | null, scale?: number) {
        scale = typeof scale !== 'undefined' ? scale : 1;
        var sc = getModelRefAs<Scripts>(ScratchJr.getActiveScript(), 'scripts')!;
        var pt = e ? Events.getTargetPoint(e) : null;
        if (pt && !pt.x) {
            pt = null;
        }
        var box = new Rectangle(el.left! / scale, el.top! / scale, el.offsetWidth / scale, el.offsetHeight / scale);
        var box2 = new Rectangle(globalx(gn('palette')!), globaly(gn('palette')!), gn('palette')!.offsetWidth, gn('palette')!.offsetHeight);
        if ((sc.flowCaret != null) && ((sc.flowCaret.prev != null)
            || (sc.flowCaret.next != null) || (sc.flowCaret.inside != null))) {
            return 'scripts';
        }
        if (box2.overlapElemBy(box, 0.66) && box2.hitRect({x: el.left! / scale, y: el.top! / scale})) {
            return 'palette';
        }
        if (pt && box2.hitRect(pt)) {
            return 'palette';
        }
        if (Palette.overlapsWith(gn('blockspalette')!, box)) { /*bugfix - returning to blocks palette should delete block*/
            return 'palette';
        }
        if (Palette.overlapsWith(gn('scripts')!, box)) {
            return 'scripts';
        }
        if (Palette.overlapsWith(gn('library')!, box)) {
            return 'library';
        }
        if (Palette.overlapsWith(gn('pages')!, box)) {
            return 'pages';
        }
        return null;
    }

    static overlapsWith (el: HTMLElement, box: Rectangle) {
        var box2 = new Rectangle(globalx(el), globaly(el), el.offsetWidth, el.offsetHeight);
        return box.intersects(box2);
    }

    static getHittedThumb (el: HTMLElement, div: HTMLElement, scale?: number) {
        scale = typeof scale !== 'undefined' ? scale : 1;
        var box1 = new Rectangle(el.left! / scale, el.top! / scale, el.offsetWidth / scale, el.offsetHeight / scale);
        var area = 0;
        var res = null;
        var dh = (div.parentNode as HTMLElement).scrollTop;
        for (var i = 0; i < div.childElementCount; i++) {
            var node = div.childNodes[i] as HTMLElement;
            if (node.nodeName == 'FORM') {
                continue;
            }
            var box2 = new Rectangle(globalx(node), globaly(node) - dh, node.offsetWidth, node.offsetHeight);
            var boxi = box1.intersection(box2);
            var a = boxi.width * boxi.height;
            if (a > area) {
                area = a;
                res = node;
            }
        }
        return res;
    }

    //////////////////////////////////////
    //  Palette Block
    /////////////////////////////////////

    static newScaledBlock (parent: HTMLElement, op: string, scale: number, dx: number, dy: number) {
        var bbx = new Block(BlockSpecs.defs[op], true, scale);
        setProps(bbx.div.style, {
            position: 'absolute',
            left: dx + 'px',
            top: dy + 'px'
        });
        parent.appendChild(bbx.div);
        return bbx;
    }

    static dropBlockFromPalette (e: MouseEvent | TouchEvent, element: HTMLElement) {
        e.preventDefault();
        switch (Palette.getLandingPlace(element, e)) {
        case 'scripts':
            PlatformBridge.analyticsEvent('editor', 'new_block', getModelRefAs<Block>(element, 'block')!.blocktype);
            var sc = ScratchJr.getActiveScript();
            var dx = localx(sc, element.left!);
            var dy = localy(sc, element.top!);
            ScriptsPane.blockDropped(sc, dx, dy);
            const activeScripts = getModelRefAs<Scripts>(ScratchJr.getActiveScript(), 'scripts')!;
            var spr = activeScripts.spr;
            const parentPage = getModelRefAs<Page>(spr.div.parentNode as HTMLElement, 'page')!;
            Undo.record({
                action: 'scripts',
                where: parentPage.id,
                who: spr.id
            });
            // Record a change for sample projects in story-starter mode
            ScratchJr.storyStart('Palette.dropBlockFromPalette');
            break;
        default:
            getModelRefAs<Scripts>(ScratchJr.getActiveScript(), 'scripts')!.deleteBlocks();
            break;
        }
        getModelRefAs<Scripts>(ScratchJr.getActiveScript(), 'scripts')!.dragList = [];
    }
}